    except IOError as e:
        raise ValueError("Cannot open configuration file: %s" % e)
    try:
        keystone_options = dict(config_file.items('keystone_authtoken'))
    except ConfigParser.NoSectionError:
        raise ValueError("Cannot find section [keystone_authtoken] " +
                         "in configuration file %s" % config_file_name)
    global_config.update(keystone_options)
    return auth_filter_factory(global_config)

